import { Link as RouterLink } from 'react-router-dom'

import { Link } from '@mui/material'

import { routes } from '@/routes'
import type { TrainingPlan } from '@/types/database'

type Props = {
  plan: TrainingPlan
}

/**
 * 같은 fm:// 폴더(또는 상하위 폴더)를 가리키는 플랜이 이미 있을 때 보여주는 안내.
 * 정책: 폴더 하나에 플랜 하나. 새 플랜 대신 기존 플랜을 재사용하도록 유도한다.
 */
export function PlanPathOverlapMessage({ plan }: Props) {
  const status = plan.completed_at ? ' (완료됨)' : ''
  return (
    <>
      같은 폴더를 가리키는 계획{' '}
      <Link component={RouterLink} to={routes.plans.detail.$path({ id: plan.id }, {})}>
        {plan.name}
      </Link>
      {status}이 이미 있습니다. 한 폴더에는 계획을 하나만 둘 수 있습니다.
      {plan.completed_at
        ? ' 이어서 훈련하려면 해당 계획에서 완료를 취소하고 전체 훈련량을 늘려 주세요.'
        : ' 해당 계획을 수정해서 사용해 주세요.'}
    </>
  )
}
